var Wc, nm;
function LT() {
  if (nm) return Wc;
  nm = 1;
  function e(t) {
    return {
      name: "STEP Part 21",
      aliases: [
        "p21",
        "step",
        "stp"
      ],
      case_insensitive: !0,
      // STEP 21 is case insensitive in theory, in practice all non-comments are capitalized.
      keywords: {
        $pattern: "[A-Z_][A-Z0-9_.]*",
        keyword: "HEADER ENDSEC DATA"
      },
      contains: [
        {
          className: "meta",
          begin: "ISO-10303-21;",
          relevance: 10
        },
        {
          className: "meta",
          begin: "END-ISO-10303-21;",
          relevance: 10
        },
        t.C_LINE_COMMENT_MODE,
        t.C_BLOCK_COMMENT_MODE,
        t.COMMENT("/\\*\\*!", "\\*/"),
        t.C_NUMBER_MODE,
        t.inherit(t.APOS_STRING_MODE, {
          illegal: null
        }),
        t.inherit(t.QUOTE_STRING_MODE, {
          illegal: null
        }),
        {
          className: "string",
          begin: "'",
          end: "'"
        },
        {
          className: "symbol",
          variants: [
            {
              begin: "#",
              end: "\\d+",
              illegal: "\\W"
            }
          ]
        }
      ]
    };
  }
  return Wc = e, Wc;
}
